package ansifilter

import "fmt"

// latexGenerator emits a LaTeX document.
type latexGenerator struct{ *Generator }

func newLaTeXGenerator() *latexGenerator {
	g := newGenerator(LATEX)
	l := &latexGenerator{g}
	g.f = l
	// A trailing \hspace*{\fill} avoids errors on empty input lines.
	g.newLineTag = "\\hspace*{\\fill}\\\\\n"
	g.styleCommentOpen = "/*"
	g.styleCommentClose = "*/"
	g.spacer = "\\ws{\\ }"
	return l
}

func (l *latexGenerator) openTag() string {
	var s string
	e := &l.elementStyle
	if e.IsBold() {
		s += "\\bfseries{}"
	}
	if e.IsItalic() {
		s += "\\itshape{}"
	}
	if e.IsFgColorSet() {
		c := e.FgColor()
		s += "\\color[rgb]{" + c.Red(LATEX) + "," + c.Green(LATEX) + "," + c.Blue(LATEX) + "}"
	}
	return "{" + s
}

func (l *latexGenerator) closeTag() string { return "}" }

func (l *latexGenerator) hyperlink(uri, txt string) string {
	return "\\href{" + uri + "}{" + txt + "}"
}

func (l *latexGenerator) generatorComment() string {
	return "% LaTeX generated by ansifilter " + Version + ", " + URL + "\n"
}

func (l *latexGenerator) header() string {
	s := "\\documentclass{article}\n"
	s += "\\usepackage{color}\n"
	s += "\\usepackage{hyperref}\n"
	s += "\\newcommand{\\ws}[1]{\\textcolor[rgb]{0,0,0}{#1}}\n"
	if l.encodingDefined() {
		s += "%\\usepackage[" + l.encoding + "]{inputenc}\n"
	}
	if l.styleSheetPath != "" {
		s += "\\input {" + l.styleSheetPath + "}\n"
	}
	s += "\\begin{document}\n"
	s += "\\section*{" + l.docTitle + "}\n"
	s += "\\ttfamily%\n"
	return s
}

func (l *latexGenerator) footer() string {
	footer := "\\end{document}\n"
	if !l.omitVersionInfo {
		footer += l.generatorComment()
	}
	return footer
}

func (l *latexGenerator) body() { l.processInput() }

func (l *latexGenerator) lineNum() {
	if l.showLineNumbers {
		if l.numberCurrentLine {
			if l.lineNumber > 1 {
				l.write(l.f.closeTag())
			}
			l.write("{\\color[rgb]{0,0,0} " + fmt.Sprintf("%5d", l.lineNumber) + "}")
			l.write(l.spacer)
			l.write(l.f.openTag())
		}
	}
}

func (l *latexGenerator) maskChar(c byte) string {
	switch c {
	case ' ':
		return l.spacer
	case '<':
		return "$<$"
	case '>':
		return "$>$"
	case '{', '}', '&', '$', '#', '%':
		return "\\" + chr(c)
	case '_':
		return "\\textunderscore "
	case '^':
		return "\\textasciicircum "
	case '\\':
		return "$\\backslash$"
	case '~':
		return "$\\sim$"
	case '|':
		return "\\textbar "
	// Braces keep '[', ']' and '*' from being read as arguments after a line
	// break, and stop consecutive hyphens merging inside a bold run.
	case '*', '[', ']', '-':
		return "{" + chr(c) + "}"
	case '\t':
		return "\t"
	default:
		if c > 0x1f {
			return chr(c)
		}
		return ""
	}
}
